from pathlib import Path
out=Path('pile-workbench')
fields=[('d','樁身直徑／方樁邊長','m',1,'樁基施工圖。圓樁填直徑；方樁填邊長。'),('db','有效樁底直徑／邊長','m',1,'樁基施工圖。未擴底與樁身相同；最大為樁身兩倍。'),('tip','樁尖深度','m',10,'由地表基準量至樁尖；須有樁尖以下鑽探資料。'),('head','樁頭／摩擦起算深度','m',0,'由地表量至樁頭或不計摩擦區底；其上方土層仍計覆土壓。'),('water','地下水位深度','m',2,'鑽探水位觀測及設計水位，向下為正；不同水位需分案檢核。'),('gp','樁材單位重','kN/m³',24,'材料規格。RC 示範 24；浮重自動扣水單位重 9.80665。'),('load','樁頭設計壓力','tf',200,'結構分析單樁分配載重，使用與所選載重情況相符的載重。'),('pull','樁頭設計拉力','tf',30,'結構分析拉拔反力，輸入正值。'),('down','已評估負摩擦附加需求','tf',0,'大地工程負摩擦分析結果；0 不代表無負摩擦風險。此欄作保守樁頭需求扣減，未求中性面。'),('fs','摩擦安全係數 FS₁','—',2.5,'112 年版表 5.3-1 推估公式：常時 2.5、短期 1.8、極限 1.2。'),('fb','端承安全係數 FS₂','—',3.5,'112 年版表 5.3-1 推估公式：常時 3.5、短期 2.5、極限 1.5。'),('fu','拉拔安全係數 FS','—',5,'112 年版表 5.3-3 推估公式：常時 5、短期 3、極限 2.4；使用受壓摩擦推估與提高係數，不再重複折減。'),('fw','原程式整體安全係數','—',2.5,'僅原程式比較模式適用。現行規範採摩擦／端承分開係數。'),('step','曲線取樣間距','m',.5,'僅控制深度結果取樣；摩擦力按土層與水位分段積分，不受取樣間距影響。')]
def inp(f):
 k,label,unit,val,help=f
 return f'<label class="field" title="{help}">{label} <small>{unit}</small><input id="{k}" type="number" step="any" value="{val}" aria-describedby="help-{k}"><span id="help-{k}">{help}</span></label>'
form=''.join(map(inp,fields))
manual=''.join(f'<tr><td>{label}</td><td>{unit}</td><td>{help}</td></tr>' for k,label,unit,val,help in fields)
html='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#12243b"><title>基樁分析工作台｜工程計算工具</title>
<style>
:root{--navy:#12243b;--ink:#1b3046;--muted:#536a7c;--line:#d6e0e7;--bg:#edf2f6;--blue:#146b98;--gold:#f0b84a;--green:#08684f;--red:#b73236}*{box-sizing:border-box}body{margin:0;font:16px/1.65 system-ui,"Microsoft JhengHei",sans-serif;color:var(--ink);background:var(--bg)}button,input,select{font:inherit}button,a.btn{min-height:44px;border:1px solid var(--line);border-radius:6px;background:white;color:var(--ink);padding:8px 14px;cursor:pointer;text-decoration:none}button:hover{border-color:var(--blue);background:#eef6fa}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f0b84a;outline-offset:2px}button.primary{background:var(--blue);color:white;border-color:var(--blue)}header{position:sticky;top:0;z-index:5;background:var(--navy);color:white;padding:12px 24px;display:flex;align-items:center;gap:16px;justify-content:space-between}header strong{font-size:20px}header small{color:#b9cbd7;font-size:14px;display:block}.tools{display:flex;flex-wrap:wrap;gap:8px}.layout{display:grid;grid-template-columns:210px minmax(0,1fr);min-height:calc(100vh - 80px)}aside{background:var(--navy);color:#c3d1dc;padding:24px 14px}aside nav{display:grid;gap:9px}aside button{text-align:left;background:transparent;border:0;color:#c3d1dc}aside button.active{background:#27415a;color:white;border-left:4px solid var(--gold)}aside a{color:#c3d1dc;font-size:14px}aside p{font-size:14px;padding:0 12px}main{min-width:0;padding:24px;max-width:1600px;width:100%;margin:auto}.heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}h1{font-size:26px;line-height:1.4;margin:0}h2{font-size:19px;margin:0 0 18px}h3{font-size:17px}p{margin:8px 0 14px}.tag{display:inline-block;padding:4px 10px;background:#dceaf2;color:#215375;border-radius:4px;font-size:14px}.card{background:white;border:1px solid var(--line);border-radius:9px;padding:22px;margin-bottom:18px;box-shadow:0 3px 10px #17314a05}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.field{display:block;font-size:14px;font-weight:600;min-width:0}.field small{color:var(--muted);float:right}.field input,.field select{width:100%;padding:9px 11px;border:1px solid #b7c8d3;border-radius:5px;background:#fbfdff;min-height:44px;color:var(--ink);margin-top:6px}.field span{display:block;font-weight:400;color:var(--muted);font-size:13px;line-height:1.5;margin-top:5px}.field input:focus+span{color:var(--blue)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0}.metric{padding:17px;background:white;border:1px solid var(--line);border-top:3px solid var(--blue);border-radius:7px}.metric small{font-size:14px;color:var(--muted);display:block}.metric strong{font-size:26px;display:block;line-height:1.5}.metric em{font-size:14px;font-style:normal}.ok{color:var(--green)}.bad{color:var(--red)}.notice{padding:12px 16px;background:#fff5d9;border:1px solid #ead28e;border-radius:6px;font-size:14px;margin:12px 0}#error{background:#fff0f0;border-color:#e4a9ab;color:#9b282b}.split{display:grid;grid-template-columns:1.05fr 1fr;gap:18px}.scroll{overflow-x:auto;max-width:100%}table{border-collapse:collapse;width:100%;font-size:14px}th{background:#edf3f7;color:#3b556c;font-weight:600}td,th{padding:10px 12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}td.num{text-align:right;font-variant-numeric:tabular-nums}svg{display:block;width:100%;height:auto}details{border-top:1px solid var(--line);padding:14px 0}summary{font-weight:600;cursor:pointer;min-height:44px}summary small{font-weight:400}.layer-header{display:flex;justify-content:space-between;align-items:center;gap:12px}.layer{background:#f6f9fc;padding:16px;border:1px solid var(--line);border-radius:7px;margin:14px 0}.layer .grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.layer h3{margin:0}footer{font-size:14px;color:var(--muted)}.mono{font-family:ui-monospace,monospace;background:#f0f4f7;padding:12px;white-space:pre-wrap;font-size:14px}section[hidden]{display:none}a{color:#12648f}#toast{position:fixed;bottom:20px;right:20px;background:var(--navy);color:white;padding:12px 20px;z-index:20;max-width:90vw}.reportonly{display:none}@media(max-width:1100px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.split{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.layer .grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){header{position:static;align-items:flex-start;flex-direction:column;padding:16px}.layout{display:block}aside{padding:8px 12px}aside nav{display:flex;overflow:auto;gap:3px}aside p,aside>a{display:none}aside button{white-space:nowrap;font-size:14px}main{padding:16px}.card{padding:16px}.grid,.layer .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.heading{align-items:flex-start;flex-direction:column}.metric strong{font-size:20px;overflow-wrap:anywhere}h1{font-size:24px}.field span{font-size:13px}.tools button{font-size:14px}.layer-header{align-items:flex-start}}@media(max-width:380px){.grid,.layer .grid{grid-template-columns:1fr}}@media print{header,aside,.tools,.noprint,#toast{display:none!important}.layout{display:block}main{padding:0;max-width:none}.card{break-inside:avoid;box-shadow:none}.metrics{grid-template-columns:repeat(4,1fr)}section{display:block!important}#panel-layers{display:none!important}#panel-settings{display:none!important}body{background:white;font-size:12px}.reportonly{display:block}table{font-size:11px}a{color:inherit}}
</style></head><body><header><div><strong>基樁分析工作台</strong><small>PILE CAPACITY · v1.0 ｜ 單樁軸向分析</small></div><div class="tools"><button id="example">載入範例</button><button id="save">儲存案件</button><button id="open">開啟案件</button><button id="offline">下載離線版</button><button id="print">列印報告／PDF</button><input type="file" id="file" accept=".json" hidden></div></header><div class="layout"><aside><nav aria-label="工作區"><button data-tab="settings" class="active">01　樁體與載重</button><button data-tab="layers">02　鑽探土層</button><button data-tab="results">03　結果與曲線</button><button data-tab="manual">04　操作說明</button><button data-tab="verification">05　公式與驗算</button></nav><p>計算單位<br>長度 m · 應力 kPa<br>力量 tf / kN / kgf</p><a href="https://jerry597640-droid.github.io/engineering-calculator-hub/">開啟工程計算工具入口網頁</a></aside><main><div class="heading"><h1 id="view-title">樁體與載重</h1><div class="tools"><span id="mode-tag" class="tag">112 年版規範</span><label>結果單位 <select id="unit" aria-label="結果單位"><option value="tf">tf（噸力）</option><option value="kN">kN</option><option value="kgf">kgf（公斤力）</option></select></label></div></div><div id="error" class="notice" role="alert" hidden></div><div class="metrics" id="metrics" aria-live="polite"></div><div id="status" class="notice"></div>
<section id="panel-settings"><div class="card"><h2>分析設定</h2><div class="grid"><label class="field">案件名稱<input id="project" value="單樁示範案"><span>供報告與案件存檔識別。</span></label><label class="field">計算模式<select id="mode"><option value="current">現行規範 · 112 年版</option><option value="legacy">原程式比較 · 修正版</option></select><span>原程式比較用於追溯舊計算，不代表規範符合。</span></label><label class="field">施工方式<select id="type"><option value="bored">鑽掘式基樁</option><option value="driven">閉口打入式基樁</option></select><span>依施工圖及施工計畫。開口樁、植入樁未納入。</span></label><label class="field">樁斷面<select id="shape"><option value="circle">圓形實心</option><option value="square">方形實心</option></select><span>中空樁須另計淨重，本版不適用。</span></label><label class="field">載重情況<select id="condition"><option value="normal">常時載重情況</option><option value="short">短期載重情況</option><option value="ultimate">極限限界狀態</option></select><span>切換時套用表 5.3-1、5.3-3「支承力推估公式」係數。</span></label><label class="field">安全係數方式<select id="safety"><option value="separate">摩擦／端承分開</option><option value="whole">原程式整體係數</option></select><span>現行規範固定分開；本版未用試樁結果計算。</span></label></div></div><div class="card"><h2>尺寸、需求與安全係數</h2><div class="grid">__FORM__</div></div><div class="notice">已設定地表為深度 0，向下為正。壓力淨可用量 = 地盤容許支承力 − 樁身浮重 − 已評估負摩擦附加需求；設計載重請填樁頭荷重，避免重複計入自重。</div></section>
<section id="panel-layers" hidden><div class="card"><div class="layer-header"><h2>鑽探土層</h2><button class="primary" id="add">新增土層</button></div><p>由淺至深輸入；深度界面由厚度自動累加。SPT 樁尖計算需要樁尖以下 1D 資料，打入樁上方需要 4D 資料。</p><div id="layers"></div><p id="profile-depth"></p></div></section>
<section id="panel-results" hidden><div class="card reportonly"><h2>輸入紀錄</h2><div id="report-inputs"></div></div><div class="split"><div class="card"><h2>地層與承載曲線</h2><div id="chart"></div><p class="muted">藍：淨壓力可用量　綠：地盤拉拔推估　虛線：壓力需求。缺乏樁尖平均 N 資料的深度不繪點。</p></div><div class="card"><h2>樁尖計算摘要</h2><div id="summary"></div><div id="warnings"></div><p id="scope"></p></div></div><div class="card"><h2>土層摩擦力分攤</h2><div class="scroll"><table id="parts"></table></div></div><div class="card"><h2>深度逐點結果</h2><button id="csv">匯出結果 CSV</button><div class="scroll"><table id="curve"></table></div></div></section>
<section id="panel-manual" hidden><div class="card"><h2>第一次使用：照著輸入</h2><ol><li>點「載入範例」，選「現行 SPT 手算範例」。</li><li>採鑽掘圓樁，直徑 1 m，樁尖 10 m，樁頭 0 m，地下水位 2 m，樁材單位重 24 kN/m³。</li><li>土層為 12 m 砂土，SPT N=20；γ=18、γsat=20 kN/m³。鑽探深度刻意大於樁尖，以涵蓋 9～11 m 的平均 N。</li><li>常時載重，FS₁=2.5、FS₂=3.5、FS拉拔=5；壓力 200 tf、拉力 30 tf；負摩擦附加需求 0 tf。</li><li>開啟「結果與曲線」核對：Qs=209.440 tf、Qb=117.810 tf、浮重=12.938 tf、淨壓力=104.498 tf、拉拔推估=54.826 tf。</li><li>此範例壓力需求 200 tf 超過可用量，故顯示 NG；拉拔 30 tf 小於推估值。範例讓你能看見超載提示，並非建議設計尺寸。</li><li>修改樁尖、樁徑或土層後即時重算。「儲存案件」下載 JSON，「開啟案件」復原；「下載離線版」保存目前案件，無網路可直接開啟 HTML。</li></ol><p>另附「原程式四層 SPT 範例」：厚度 0.9／2.5／0.5／2.6 m，N=7／13／20／32。此案採原程式比較模式，避免將未涵蓋樁尖下方的資料誤當現行驗算。</p></div><div class="card"><h2>樁體與載重欄位：填什麼、從哪裡來</h2><div class="scroll"><table><thead><tr><th>欄位</th><th>單位</th><th>定義與資料來源</th></tr></thead><tbody>__MANUAL__</tbody></table></div></div><div class="card"><h2>土層欄位與資料來源</h2><div class="scroll"><table><tr><th>欄位</th><th>填入資料與來源</th></tr><tr><td>名稱／厚度／土性</td><td>鑽探柱狀圖、地層分界；厚度 m。土性依土壤分類判定為砂性或黏性；岩層與卵礫石不得直接套用砂土 SPT 公式。</td></tr><tr><td>γ／γsat</td><td>天然與飽和單位重 kN/m³，取土壤試驗／地質報告；地下水以下自行減 γw=9.80665。請勿填浮單位重，避免重複扣水。</td></tr><tr><td>SPT N</td><td>鑽探標準貫入試驗紀錄，同一層內的代表值；有多筆試驗時拆成適當土層。樁端採規範指定上下範圍的厚度加權平均，N̄上限50；本工具不自動將 N60、液化修正 N 或拒錘次數換成 N。</td></tr><tr><td>Su／α／Nc</td><td>Su：不排水剪力強度 kPa，取 UU/CU、單壓或現地試驗。α：試樁／同類施工經驗，現行參數法需自行確認，0.25～1。Nc：樁端係數，深層黏土常取9，仍須評估貫入承載層深度。</td></tr><tr><td>K／δ／φ</td><td>K為樁土側向壓力係數；δ為樁土介面摩擦角（°）；φ為土壤內摩擦角（°），來自有效應力試驗與材料介面／施工經驗。現行參數法直接使用 Nq，不由φ自動轉換。</td></tr><tr><td>Nq／Nγ／臨界深度</td><td>無因次端承係數由規範解說、試樁與地質設計評估。臨界深度以地表以下 m 表示，用於限制砂土有效覆土壓；0表示未限制，須有評估依據。現行砂土 qb=σ′Nq+0.5γ′DbNγ。</td></tr><tr><td>密度</td><td>只供原程式「典型法」，鬆／中／密控制臨界深度與舊係數，不能用選項代替土壤試驗。</td></tr></table></div></div><div class="card"><h2>如何選計算法</h2><p>SPT：現行規範僅限砂性土，fs=min(N/3,15) tf/m²；鑽掘 qb=7.5N̄、閉口打入 qb=30N̄ tf/m²。黏土採參數法 fs=αSu、qb=NcSu。砂土參數法採 Kσ′tanδ 與輸入的端承係數。不同土層可選不同方法，但樁端 SPT 平均範圍須全為砂性土。</p><p>原程式比較保留典型法、φ 查表詳細法與舊 SPT 黏土經驗式。原始 φ 與 Nq 陣列長度不一致，超過40°原碼可能越界；本版限制有效範圍，不推測缺漏點。α表僅0～200 kPa，超出改用現行參數法。</p><p>結果判定「軸向承載檢核通過」只涵蓋本表需求與地盤推估。尚須完成規範第5.4節群樁、第5.5節變位、第5.6節樁體結構、第5.7節試樁、側向力與液化；均未以綠燈宣告完成。</p><p>擴底樁可比較壓力地盤支承力，但未建立擴底體積與拉拔破壞模式，拉拔顯示「待專項分析」，不得只用75%上限視為完成。</p></div></section>
<section id="panel-verification" hidden><div class="card"><h2>規範依據與公式追溯</h2><p><a href="https://www.nlma.gov.tw/ch/legislation/regsearch/962" target="_blank" rel="noopener">國土署：建築物基礎構造設計規範</a>｜112.06.20 修正，113.01.01 生效。2026.10.05 查核。</p><p><a href="https://www.nlma.gov.tw/uploads/files/53651dae74223e6599e20838bb8c4f2a.pdf" target="_blank" rel="noopener">112年版官方全文</a>：第5.3.1節、表5.3-1／5.3-2，p.5-15～5-17；第5.3.2節、表5.3-3，p.5-30～5-32。</p><div class="mono">Qu = Qs + Qb\nQs = Σ(U × Δz × fs)\nQb = Ab × qb\nQa = Qs/FS₁ + Qb/FS₂\n淨壓力 = max(0, Qa − W′p − 已評估負摩擦附加需求)\nRa = Qs/FS拉拔 + W′p（均勻斷面）\nW′p = A樁身[γp × 水上長度 + (γp−γw) × 水下長度]\n1 tf = 9.80665 kN = 1000 kgf（公斤力，不是質量 kg）</div><div class="scroll"><table><tr><th>載重情況</th><th>FS₁</th><th>FS₂</th><th>FS拉拔</th></tr><tr><td>常時／推估公式</td><td>2.5</td><td>3.5</td><td>5.0</td></tr><tr><td>短期／推估公式</td><td>1.8</td><td>2.5</td><td>3.0</td></tr><tr><td>極限／推估公式</td><td>1.2</td><td>1.5</td><td>2.4</td></tr></table></div><p>本版不採載重試驗較低安全係數，因為未輸入試樁極限分量。參數法係數需有場址證據；只換係數不能取代地震性能與變位檢核。</p></div><div class="card"><h2>獨立手算基準</h2><div class="mono">圓樁 D=1 m，L=10 m，砂土 N=20\nU=π m，Ab=π/4 m²\nfs=20/3 tf/m²，qb=7.5×20=150 tf/m²\nQs=(20/3)×π×10=209.439510 tf\nQb=150×π/4=117.809725 tf\nQa=209.439510/2.5+117.809725/3.5=117.435725 tf\nW′p=(π/4)[24×2+(24−9.80665)×8]/9.80665=12.938012 tf\n淨壓力=104.497713 tf\nRa=209.439510/5+12.938012=54.825915 tf</div><p>驗證涵蓋：多層 SPT 分攤、樁尖上下平均 N、打入／鑽掘差異、N與fs上限、浮重、圓方斷面、分段水位積分、α/Nc邊界、無效輸入及離線操作。詳細紀錄附於下載套件。</p></div><div class="card"><h2>原始程式與修正</h2><p>來源：20121009 pile.zip → WindowsApplication1/PileCapacityAnalysis.vb；Compute_Engine（680～945行）、CAL_FRICTIONCOEF（1014行）、CAL_Nc（1035行）。</p><ul><li>原碼固定200步右端矩形累加；改按土層界面、水位、臨界深度分段精確積分。</li><li>原碼全剖面單一土壤單位重；改逐層輸入，累加有效覆土壓。</li><li>原碼詳細法中途換tf再回kN；改內部統一kN/m/kPa。</li><li>原碼樁重用樁底面積；改用樁身面積，擴底體積需另算。</li><li>原碼φ表12點、Nq表13點；只採已明確對應的12點，超範圍拒絕。</li><li>原碼 SPT 直接用樁尖層 N；現行模式依表5.3-2取上下範圍平均，缺資料即停止判定。</li><li>原碼黏土SPT式僅保留比較；現行模式拒絕黏土SPT，改參數法。</li></ul></div></section><footer>基樁分析工作台 v1.0 · 公式推估／單樁軸向。請保存輸入資料來源及工程判斷依據。</footer></main></div><div id="toast" role="status" hidden></div><script id="case-data" type="application/json">null</script><script>__ENGINE__</script><script>__APP__</script></body></html>'''
app=Path('pile-workbench/app.js').read_text()
html=html.replace('__FORM__',form).replace('__MANUAL__',manual).replace('__ENGINE__',(out/'engine.js').read_text()).replace('__APP__',app)
